-- (version 20261112201101). Numero 0140 porque 0100 ya estaba tomado.
-- Carga inicial del catalogo publico de Cochi. Precios expresados en USD.

update public.tenants set currency = 'USD' where slug = 'cochi'; with catalog(name, category, price, description, active) as (values ('Ración individual de Ribs a las BBQ','Costillas a la BBQ',9.00,'250 g de costillas de cerdo a la BBQ, papas fritas y ensalada César.',true),('¼ de costilla sola','Costillas a la BBQ',7.00,'250 g de costillas a la BBQ.',true),('½ kilo de costilla sola','Costillas a la BBQ',14.00,'500 g de costillas a la BBQ.',true),('1 kilo de costilla sola','Costillas a la BBQ',28.00,'1000 g de costillas a la BBQ.',true),('Shawarma de pollo crispy','Shawarmas',8.00,'Pan árabe, lechuga, cebolla, tomate, pepinillos, perejil, papas hilachas, pollo crispy y salsas árabes.',true),('Shawarma de César','Shawarmas',8.00,'Pan árabe, lechuga, cebolla, tomate, crotones, queso pecorino, papas hilachas, pepinillos, pollo crispy y salsa César de la casa.',true),('Bandeja 3 carnes','Bandejas',17.00,'200 g de lomito, 200 g de costillas a la BBQ, 250 g de tenders o alitas y papas fritas.',true),('Bandeja costilla y lomito','Bandejas',14.00,'200 g de lomito, 200 g de costillas a la BBQ, papas fritas y ensalada César.',true),('Bandeja costilla y pollo','Bandejas',11.00,'200 g de tenders o alitas, 200 g de costillas a la BBQ, papas fritas y ensalada César.',true),('Classic Box','Arroz chino',4.00,'23 onzas de arroz chino.',true),('Mega Box','Arroz chino',6.00,'32 onzas de arroz chino.',true),('Arroz especial con alitas','Arroz chino',10.00,'Arroz chino, papas fritas o ensalada y alitas de pollo.',true),('Arroz especial con costillas','Arroz chino',12.00,'Arroz chino, papas fritas o ensalada y costillas a la BBQ.',true),('Ración de churrasco','Churrasco',12.00,'300 g de carne, papas fritas y ensalada César.',true),('Ración individual de tenders','Tenders y alitas',7.00,'250 g de tenders de pollo, papas fritas y ensalada César.',true),('Ración individual de alitas','Tenders y alitas',6.00,'250 g de alitas de pollo, papas fritas y ensalada César.',true),('½ pollo asado','Pollo asado',10.00,'½ pollo asado, ración de yuca, guasacaca y refresco de 1 litro.',false),('Pollo entero','Pollo asado',18.00,'Pollo entero, ración de yuca, guasacaca y refresco de 2 litros.',false),('Ensalada César','Adicionales',5.00,'Ensalada César.',true),('Ensalada César con pollo','Adicionales',7.00,'Ensalada César con pollo.',true),('Ración de papas pequeña','Adicionales',1.50,'Ración pequeña de papas fritas.',true),('Ración de papas grande','Adicionales',3.50,'Ración grande de papas fritas.',true),('Refresco 1 litro','Bebidas',1.50,'Refresco de 1 litro.',true),('Refresco 2 litros','Bebidas',2.50,'Refresco de 2 litros.',true),('Marquesa de chocolate','Postres',3.00,'Marquesa de chocolate de Cochi Dulce.',true)) insert into public.products (tenant_id,type,name,price,active,category,description) select t.id,'composite',c.name,c.price,c.active,c.category,c.description from public.tenants t cross join catalog c where t.slug='cochi' and not exists (select 1 from public.products p where p.tenant_id=t.id and lower(btrim(p.name))=lower(btrim(c.name)));
